693	}
694	
695	/* ═══════════════════════════════════════════════════
696	   DESIGN SYSTEM — StatusCard
697	   ═══════════════════════════════════════════════════ */
698	
699	.status-card {
700	  border-radius: var(--radius-lg);
701	  padding: 16px;
702	  display: flex;
703	  flex-direction: column;
704	  gap: 8px;
705	}
706	
707	.status-card-default {
708	  background: var(--color-surface);
709	  border: 1px solid var(--color-border);
710	}
711	
712	.status-card-orange {
713	  background: var(--color-orange-light);
714	  border: 1px solid #FCD9C7;
715	}
716	
717	.status-card-blue {
718	  background: #EEF2FF;
719	  border: 1px solid #D8E2FD;
720	}
721	
722	.status-card-success {
723	  background: #DCFCE7;
724	  border: 1px solid #BBF7D0;
725	}
726	
727	.status-card-navy {
728	  background: var(--color-navy);
729	  border: 1px solid var(--color-navy-light);
730	  color: white;
731	}
732	
733	.status-card-header {
734	  display: flex;
735	  justify-content: space-between;
736	  align-items: flex-start;
737	}
738	
739	.status-card-title {
740	  font-size: 12px;
741	  font-weight: 600;
742	  text-transform: uppercase;
743	  letter-spacing: 0.04em;
