745	
746	.status-card-title-default { color: var(--color-text-tertiary); }
747	.status-card-title-navy { color: rgba(255,255,255,0.7); }
748	
749	.status-card-value {
750	  font-family: var(--font-heading);
751	  font-size: 1.5rem;
752	  font-weight: 700;
753	  letter-spacing: -0.02em;
754	  line-height: 1.1;
