756	
757	.status-card-value-default { color: var(--color-navy); }
758	.status-card-value-navy { color: white; }
759	
760	.status-card-subtitle {
761	  font-size: 12px;
762	}
763	
764	.status-card-subtitle-default { color: var(--color-text-tertiary); }
765	.status-card-subtitle-navy { color: rgba(255,255,255,0.6); }
766	
767	.status-card-trend {
768	  display: flex;
769	  align-items: center;
770	  gap: 4px;
771	}
772	
773	.status-card-trend-value {
774	  font-size: 12px;
775	  font-weight: 700;
776	}
777	
778	.status-card-trend-up { color: var(--color-success); }
779	.status-card-trend-down { color: var(--color-error); }
780	.status-card-trend-neutral { color: var(--color-text-tertiary); }
781	
782	/* ═══════════════════════════════════════════════════
783	   DESIGN SYSTEM — ListItem
784	   ═══════════════════════════════════════════════════ */
785	
786	.list-item-title-row {
787	  display: flex;
788	  align-items: center;
789	  gap: 8px;
790	}
791	
792	.list-item-link {
793	  text-decoration: none;
794	  color: inherit;
795	}
796	
797	.list-item-icon {
798	  width: 40px;
799	  height: 40px;
800	  border-radius: var(--radius-md);
801	  display: flex;
802	  align-items: center;
803	  justify-content: center;
804	  flex-shrink: 0;
805	}
806	
807	.step-check-icon {
808	  margin-right: 4px;
809	  vertical-align: -2px;
810	}
811	
812	/* ═══════════════════════════════════════════════════
813	   DESIGN SYSTEM — ProgressSteps
814	   ═══════════════════════════════════════════════════ */
815	
816	.steps-list {
817	  display: flex;
818	  gap: 0;
819	  margin: 0;
820	  padding: 0;
821	  list-style: none;
822	}
823	
824	.steps-list-vertical {
825	  flex-direction: column;
826	}
827	
828	.steps-list-horizontal {
829	  align-items: center;
830	  width: 100%;
831	}
832	
833	.step-item-vertical {
834	  display: flex;
835	  gap: 12px;
836	}
837	
838	.step-dot-col {
839	  display: flex;
