@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700;9..40,800&family=Inter:wght@400;500;600;700&display=swap');
@import "tailwindcss";
@import "@heroui/styles";

/* ═══════════════════════════════════════════════════
   GCCStartup v2.0 — Design Tokens & Foundation
   ═══════════════════════════════════════════════════ */

@theme {
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;

  --color-orange: #F26522;
  --color-orange-dark: #D4561A;
  --color-orange-light: #FEF1E9;
  --color-orange-hover: #E85A18;

  --color-navy: #14204A;
  --color-navy-light: #1E2D5A;
  --color-navy-subtle: #F0F2F8;

  --color-surface: #FFFFFF;
  --color-surface-alt: #F8FAFC;
  --color-canvas: #F1F3F7;
  --color-card: #FFFFFF;

  --color-border: #E8ECF1;
  --color-border-hover: #D1D8E3;

  --color-text: #1A1D26;
  --color-text-secondary: #5A6178;
  --color-text-tertiary: #8C93A7;
  --color-text-muted: #B4BAC9;

  --color-success: #16A34A;
  --color-success-light: #DCFCE7;
  --color-error: #DC2626;
  --color-error-light: #FEE2E2;
  --color-warning: #D97706;
  --color-warning-light: #FEF3C7;
  --color-info: #2563EB;
  --color-info-light: #DBEAFE;
  --color-whatsapp: #25D366;

  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 24px;
  --radius-pill: 9999px;

  --shadow-xs: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 16px 48px rgba(0,0,0,0.1), 0 8px 16px rgba(0,0,0,0.06);
  --shadow-orange: 0 4px 16px rgba(242,101,34,0.25);
  --shadow-card: 0 2px 8px rgba(0,0,0,0.04), 0 0 1px rgba(0,0,0,0.06);

  --spacing-page: 20px;
  --spacing-section: 28px;
}

/* ─── Variable Aliases (for inline var() usage in components) ─── */
:root {
  --navy: var(--color-navy);
  --orange: var(--color-orange);
  --text-secondary: var(--color-text-secondary);
  --text-tertiary: var(--color-text-tertiary);
  --text-muted: var(--color-text-secondary);
  --border: var(--color-border);
  --surface: var(--color-surface);
  --surface-alt: var(--color-surface-alt);
  --success: var(--color-success);
  --error: var(--color-error);
  --warning: var(--color-warning);
  --blue: var(--color-info);
  --orange-lt: var(--color-orange-light);
  --sand: #F5F0E8;
  --card-hover: rgba(0,0,0,0.03);
}

/* ─── Base Reset ─── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  -webkit-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

html, body { height: 100%; overflow-x: hidden; }

body {
  font-family: var(--font-sans);
  background: var(--color-canvas);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100dvh;
}

/* ─── Accessibility ─── */
:focus-visible {
  outline: 2px solid var(--color-orange);
  outline-offset: 2px;
  border-radius: var(--radius-xs);
}

.skip-link {
  position: absolute;
  top: -9999px;
  left: 16px;
  z-index: 9999;
  padding: 8px 16px;
  background: var(--color-orange);
  color: #FFFFFF;
  font-weight: 700;
  font-size: 13px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: var(--shadow-md);
  transition: top 0.2s ease;
}
.skip-link:focus { top: 16px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ─── Custom Scrollbar ─── */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--color-border-hover); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: var(--color-text-muted); }

/* ═══════════════════════════════════════════════════
   APP SHELL
   ═══════════════════════════════════════════════════ */

.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
  max-width: 100vw;
  overflow-x: hidden;
  background: var(--color-canvas);
}

.app-page-content {
  flex: 1;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 0 var(--spacing-page);
  padding-bottom: 100px;
}
@media (min-width: 768px) { .app-page-content { max-width: 720px; padding: 0 32px 48px; } }
@media (min-width: 1024px) { .app-page-content { max-width: 960px; } }

/* ═══════════════════════════════════════════════════
   HEADER
   ═══════════════════════════════════════════════════ */

.app-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  height: 56px;
  display: flex;
  align-items: center;
  padding: 0 var(--spacing-page);
}

.app-header-inner {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
@media (min-width: 768px) { .app-header-inner { max-width: 720px; } }
@media (min-width: 1024px) { .app-header-inner { max-width: 960px; } }

.header-left { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.header-center { flex: 0 0 auto; text-align: center; }
.header-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

.header-title {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-back-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: var(--color-surface-alt);
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--color-text);
  transition: background 0.15s ease;
  flex-shrink: 0;
}
.header-back-btn:hover { background: var(--color-border); }

.header-icon-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--color-text-secondary);
  transition: all 0.15s ease;
  position: relative;
  flex-shrink: 0;
}
.header-icon-btn:hover { background: var(--color-surface-alt); color: var(--color-text); }

.header-badge {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--color-orange);
  color: #FFFFFF;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-surface);
}

.brand-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 12px var(--spacing-page) 14px;
}

.brand-header-inner { width: 100%; max-width: 480px; margin: 0 auto; }

/* ═══════════════════════════════════════════════════
   BOTTOM TAB BAR
   ═══════════════════════════════════════════════════ */

.tab-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 6px 8px calc(6px + env(safe-area-inset-bottom, 0px));
}

.tab-bar-inner {
  max-width: 480px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-around;
}
@media (min-width: 768px) { .tab-bar-inner { max-width: 720px; } }

.tab-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 4px 12px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-muted);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 0.15s ease;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  font-family: var(--font-sans);
}
.tab-item.active { color: var(--color-orange); }

.tab-item .tab-icon { width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; }

.tab-center-btn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-orange);
  color: #FFFFFF;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-orange);
  margin-top: -20px;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  -webkit-tap-highlight-color: transparent;
}
.tab-center-btn:hover { transform: scale(1.05); box-shadow: 0 6px 20px rgba(242,101,34,0.35); }
.tab-center-btn:active { transform: scale(0.95); }

/* ═══════════════════════════════════════════════════
   CARDS
   ═══════════════════════════════════════════════════ */

.card {
  background: var(--color-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card-interactive, .card-hover { cursor: pointer; }
.card-interactive:hover, .card-hover:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.card-interactive:active, .card-hover:active { transform: scale(0.98); }

.card-padded { padding: 16px; }
.card-padded-sm { padding: 12px; }
.card-flat { background: var(--color-surface-alt); box-shadow: none; }
.card-orange { background: var(--color-orange-light); box-shadow: none; }
.card-orange-lt { background: var(--color-orange-light); }
.card-navy { background: var(--color-navy); color: #FFFFFF; box-shadow: none; }
.card-bordered { box-shadow: none; border: 1px solid var(--color-border); }
.card-sand { background: var(--sand); }
.card-blue-lt { background: var(--color-info-light); }

/* ═══════════════════════════════════════════════════
   BUTTONS
   ═══════════════════════════════════════════════════ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-weight: 600;
  font-family: var(--font-sans);
  border: none;
  cursor: pointer;
  line-height: 1.2;
  text-decoration: none;
  transition: all 0.18s ease;
  -webkit-tap-highlight-color: transparent;
  white-space: nowrap;
}

.btn-primary { background: var(--color-orange); color: #FFFFFF; box-shadow: var(--shadow-orange); }
.btn-primary:hover { background: var(--color-orange-hover); }
.btn-primary:active { transform: scale(0.97); }

.btn-secondary { background: var(--color-surface); color: var(--color-text); border: 1.5px solid var(--color-border); }
.btn-secondary:hover { background: var(--color-surface-alt); border-color: var(--color-border-hover); }

.btn-ghost { background: transparent; color: var(--color-text-secondary); padding: 8px 16px; }
.btn-ghost:hover { background: var(--color-surface-alt); }

.btn-navy { background: var(--color-navy); color: #FFFFFF; }
.btn-navy:hover { background: var(--color-navy-light); }

.btn-sm { padding: 8px 16px; font-size: 12px; }
.btn-lg { padding: 16px 32px; font-size: 16px; }
.btn-full { width: 100%; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none !important; }

@keyframes btnSpin { to { transform: rotate(360deg); } }

/* ═══════════════════════════════════════════════════
   BADGES
   ═══════════════════════════════════════════════════ */

.badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: var(--radius-pill); font-size: 11px; font-weight: 700; letter-spacing: 0.01em; line-height: 1.3; }
.badge-orange { background: var(--color-orange-light); color: var(--color-orange); }
.badge-navy { background: var(--color-navy-subtle); color: var(--color-navy); }
.badge-success { background: var(--color-success-light); color: var(--color-success); }
.badge-error { background: var(--color-error-light); color: var(--color-error); }
.badge-warning { background: var(--color-warning-light); color: var(--color-warning); }
.badge-info { background: var(--color-info-light); color: var(--color-info); }
.badge-sm { padding: 2px 8px; font-size: 10px; }

/* ═══════════════════════════════════════════════════
   FORMS & INPUTS
   ═══════════════════════════════════════════════════ */

.input-field {
  width: 100%;
  height: 48px;
  padding: 0 16px;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-family: var(--font-sans);
  color: var(--color-text);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.input-field:focus { border-color: var(--color-orange); box-shadow: 0 0 0 3px rgba(242,101,34,0.12); }
.input-field::placeholder { color: var(--color-text-muted); }

.input-label { display: block; font-size: 13px; font-weight: 600; color: var(--color-text); margin-bottom: 6px; }
.input-helper { font-size: 12px; color: var(--color-text-tertiary); margin-top: 4px; }
.input-error { font-size: 12px; color: var(--color-error); margin-top: 4px; }

/* ═══════════════════════════════════════════════════
   SEARCH BAR
   ═══════════════════════════════════════════════════ */

.search-bar { position: relative; width: 100%; }
.search-bar input {
  width: 100%;
  height: 48px;
  padding: 0 16px 0 44px;
  background: var(--color-surface-alt);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-family: var(--font-sans);
  color: var(--color-text);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}
.search-bar input:focus { border-color: var(--color-orange); box-shadow: 0 0 0 3px rgba(242,101,34,0.12); background: var(--color-surface); }
.search-bar input::placeholder { color: var(--color-text-muted); }

/* ═══════════════════════════════════════════════════
   MODAL / BOTTOM SHEET
   ═══════════════════════════════════════════════════ */

.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 200; display: flex; align-items: flex-end; justify-content: center; padding: 0; }
@media (min-width: 768px) { .modal-backdrop { align-items: center; padding: 24px; } }

.modal-content { background: var(--color-surface); border-radius: var(--radius-2xl) var(--radius-2xl) 0 0; width: 100%; max-width: 480px; max-height: 90vh; overflow-y: auto; padding: 20px; }
@media (min-width: 768px) { .modal-content { border-radius: var(--radius-2xl); max-height: 80vh; } }

.modal-handle { width: 36px; height: 4px; border-radius: 2px; background: var(--color-border-hover); margin: 0 auto 16px; }
@media (min-width: 768px) { .modal-handle { display: none; } }

/* ═══════════════════════════════════════════════════
   TOAST / SNACKBAR
   ═══════════════════════════════════════════════════ */

.toast-container { position: fixed; top: 16px; left: 50%; transform: translateX(-50%); z-index: 300; display: flex; flex-direction: column; gap: 8px; pointer-events: none; width: calc(100% - 32px); max-width: 400px; }
.toast { background: var(--color-navy); color: #FFFFFF; padding: 12px 16px; border-radius: var(--radius-md); font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 10px; box-shadow: var(--shadow-lg); pointer-events: auto; animation: toastIn 0.3s ease-out; }
.toast-success { background: var(--color-success); }
.toast-error { background: var(--color-error); }
.toast-warning { background: var(--color-warning); }

@keyframes toastIn { from { opacity: 0; transform: translateY(-12px); } to { opacity: 1; transform: translateY(0); } }

/* ═══════════════════════════════════════════════════
   PROGRESS
   ═══════════════════════════════════════════════════ */

.progress-track { width: 100%; height: 6px; background: var(--color-border); border-radius: var(--radius-pill); overflow: hidden; }
.progress-fill { height: 100%; border-radius: var(--radius-pill); background: var(--color-orange); transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }

/* ═══════════════════════════════════════════════════
   SECTIONS & EMPTY STATE
   ═══════════════════════════════════════════════════ */

.section-title { font-family: var(--font-heading); font-size: 1.05rem; font-weight: 700; color: var(--color-text); }

.empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 48px 24px; text-align: center; }
.empty-state-icon { width: 72px; height: 72px; border-radius: 50%; background: var(--color-surface-alt); display: flex; align-items: center; justify-content: center; margin-bottom: 16px; color: var(--color-text-muted); }
.empty-state-title { font-family: var(--font-heading); font-size: 1.1rem; font-weight: 700; color: var(--color-text); margin-bottom: 6px; }
.empty-state-desc { font-size: 14px; color: var(--color-text-tertiary); max-width: 280px; line-height: 1.5; margin-bottom: 20px; }

/* ═══════════════════════════════════════════════════
   PAGE HEADER
   ═══════════════════════════════════════════════════ */

.page-header-eyebrow { font-size: 11px; font-weight: 800; color: var(--color-orange); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 4px; }
.page-header-title { font-family: var(--font-heading); font-size: 1.5rem; font-weight: 800; color: var(--color-text); margin: 0; line-height: 1.2; }
.page-header-subtitle { font-size: 13px; color: var(--color-text-secondary); margin-top: 4px; }

/* ═══════════════════════════════════════════════════
   ANIMATIONS
   ═══════════════════════════════════════════════════ */

@keyframes slideUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
.animate-slide-up { animation: slideUp 0.3s ease-out both; }

/* ═══════════════════════════════════════════════════
   SHORTHAND COLOR UTILITIES
   (Tailwind v4 @theme generates: text-navy, bg-navy, etc. from --color-navy.
    These shorthand aliases exist for components using non-standard names.)
   ═══════════════════════════════════════════════════ */

.text-secondary { color: var(--color-text-secondary); }
.text-tertiary { color: var(--color-text-tertiary); }
.text-muted { color: var(--color-text-muted); }

/* ═══════════════════════════════════════════════════
   DESIGN SYSTEM — TopBar Brand & Notifications
   ═══════════════════════════════════════════════════ */

.topbar-brand-link {
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}

.topbar-brand-logo {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: var(--color-orange-light);
  border: 1px solid #FCD9C7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 800;
  color: var(--color-orange);
  font-family: var(--font-heading);
}

.topbar-brand-text {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  color: var(--color-navy);
  letter-spacing: -0.02em;
}

.topbar-brand-highlight {
  color: var(--color-orange);
}

/* Notification Drawer */
.notif-drawer {
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.notif-drawer-content {
  display: flex;
  flex-direction: column;
  animation: slideUp 0.25s ease-out;
}

.notif-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 14px;
}

.notif-drawer-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.notif-drawer-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 700;
  color: var(--color-navy);
}

.notif-bar-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.notif-unread-count {
  font-size: 12px;
  color: var(--color-text-tertiary);
}

.notif-mark-all-btn {
  background: none;
  border: none;
  color: var(--color-orange);
  font-weight: 700;
  cursor: pointer;
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-sans);
}

.notif-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.notif-empty {
  padding: 40px 16px;
}

.notif-empty-text {
  font-size: 13px;
  color: var(--color-text-muted);
}

.notif-item {
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.notif-item-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.notif-item-name {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.notif-item-name-unread {
  color: var(--color-orange);
}

.notif-item-name-read {
  color: var(--color-text-tertiary);
}

.notif-item-time {
  font-size: 10px;
  color: var(--color-text-muted);
}

.notif-item-message {
  font-size: 12px;
  color: var(--color-navy);
  line-height: 1.4;
}

.notif-footer {
  padding-top: 14px;
  margin-top: auto;
}

.notif-footer-link {
  text-decoration: none;
  font-size: 12px;
}

/* ═══════════════════════════════════════════════════
   DESIGN SYSTEM — StatusCard
   ═══════════════════════════════════════════════════ */

.status-card {
  border-radius: var(--radius-lg);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.status-card-default {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
}

.status-card-orange {
  background: var(--color-orange-light);
  border: 1px solid #FCD9C7;
}

.status-card-blue {
  background: #EEF2FF;
  border: 1px solid #D8E2FD;
}

.status-card-success {
  background: #DCFCE7;
  border: 1px solid #BBF7D0;
}

.status-card-navy {
  background: var(--color-navy);
  border: 1px solid var(--color-navy-light);
  color: white;
}

.status-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.status-card-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.status-card-title-default { color: var(--color-text-tertiary); }
.status-card-title-navy { color: rgba(255,255,255,0.7); }

.status-card-value {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.status-card-value-default { color: var(--color-navy); }
.status-card-value-navy { color: white; }

.status-card-subtitle {
  font-size: 12px;
}

.status-card-subtitle-default { color: var(--color-text-tertiary); }
.status-card-subtitle-navy { color: rgba(255,255,255,0.6); }

.status-card-trend {
  display: flex;
  align-items: center;
  gap: 4px;
}

.status-card-trend-value {
  font-size: 12px;
  font-weight: 700;
}

.status-card-trend-up { color: var(--color-success); }
.status-card-trend-down { color: var(--color-error); }
.status-card-trend-neutral { color: var(--color-text-tertiary); }

/* ═══════════════════════════════════════════════════
   DESIGN SYSTEM — ListItem
   ═══════════════════════════════════════════════════ */

.list-item-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.list-item-link {
  text-decoration: none;
  color: inherit;
}

.list-item-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.step-check-icon {
  margin-right: 4px;
  vertical-align: -2px;
}

/* ═══════════════════════════════════════════════════
   DESIGN SYSTEM — ProgressSteps
   ═══════════════════════════════════════════════════ */

.steps-list {
  display: flex;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.steps-list-vertical {
  flex-direction: column;
}

.steps-list-horizontal {
  align-items: center;
  width: 100%;
}

.step-item-vertical {
  display: flex;
  gap: 12px;
}

.step-dot-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 24px;
}

.step-dot-col .step-dot {
  flex-shrink: 0;
  z-index: 1;
}

.step-connector-v {
  width: 2px;
  flex: 1;
  min-height: 24px;
  border-radius: 2px;
}

.step-connector-v-completed { background: var(--color-success); }
.step-connector-v-pending { background: var(--color-border); }

.step-content-vertical {
  flex: 1;
}

.step-content-vertical-pad {
  padding-bottom: 20px;
}

.step-label {
  font-size: 14px;
  line-height: 1.3;
}

.step-label-completed { font-weight: 600; color: var(--color-success); }
.step-label-current { font-weight: 700; color: var(--color-navy); }
.step-label-pending { font-weight: 600; color: var(--color-text-muted); }

.step-desc {
  font-size: 12px;
  color: var(--color-text-tertiary);
  margin-top: 2px;
}

.step-item-horizontal {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.step-label-h {
  font-size: 10px;
  text-align: center;
  line-height: 1.2;
}

.step-label-h-completed { font-weight: 600; color: var(--color-success); }
.step-label-h-current { font-weight: 700; color: var(--color-navy); }
.step-label-h-pending { font-weight: 600; color: var(--color-text-muted); }

.step-connector-h {
  flex: 1;
  height: 2px;
  border-radius: 2px;
  margin-top: -14px;
}

.step-connector-h-completed { background: var(--color-success); }
.step-connector-h-pending { background: var(--color-border); }

/* ═══════════════════════════════════════════════════
   DESIGN SYSTEM — PageHeader
   ═══════════════════════════════════════════════════ */

.page-header-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.page-header-text {
  flex: 1;
}

.page-header-action {
  flex-shrink: 0;
  margin-top: 4px;
}

import type { Metadata, Viewport } from 'next';
import '@/styles/globals.css';
import AppChrome from '@/components/layout/AppChrome';

export const metadata: Metadata = {
  title: 'GCCStartup',
  description:
    'Form companies in UAE, Hong Kong, Singapore & Bahrain with guaranteed banking, 0% tax structures, and complete nominee privacy.',
  manifest: '/manifest.json',
  appleWebApp: {
    capable: true,
    statusBarStyle: 'black-translucent',
    title: 'GCCStartup',
  },
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  maximumScale: 5,
  themeColor: '#14204A',
  viewportFit: 'cover',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <link rel="apple-touch-icon" href="/icons/icon-192.png" />
        <link rel="apple-touch-icon" sizes="152x152" href="/icons/icon-152.png" />
        <meta name="apple-mobile-web-app-capable" content="yes" />
        <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
        <meta name="theme-color" content="#14204A" />
      </head>
      <body suppressHydrationWarning>
        <a href="#main-content" className="skip-link">
          Skip to main content
        </a>
        <AppChrome>{children}</AppChrome>
      </body>
    </html>
  );
}

