const variantMap: Record<string, HeroButtonVariant> = {
  primary: 'primary',
  secondary: 'secondary',
  ghost: 'ghost',
  danger: 'danger',
  navy: 'primary',
};

export function Button({
  variant = 'primary',
  size = 'md',
  fullWidth = false,
  isLoading = false,
  leftIcon,
  rightIcon,
  disabled,
  className = '',
  children,
  ...props
}: ButtonProps) {
  return (
    <HeroButton
      {...props}
      variant={variantMap[variant] || 'primary'}
      size={size}
      fullWidth={fullWidth}
      isDisabled={disabled || isLoading}
      className={className}
    >
      {isLoading ? (
        <Loader2 size={16} className="animate-spin" />
      ) : (
        <>
          {leftIcon}
          {children}
          {rightIcon}
        </>
      )}
    </HeroButton>
  );
}

