const variantMap: Record<string, HeroButtonVariant> = {
  primary: 'primary',
  secondary: 'secondary',
  ghost: 'ghost',
  danger: 'danger',
  // HeroUI has no distinct "navy" variant slot — its 'primary' variant is
  // hardcoded to the bridged --accent (orange) fill. We use 'primary' for
  // shape/padding and override the fill color via className below.
  navy: 'primary',
};

// HeroUI variants without a matching brand color get their fill overridden
// here rather than through the (fixed, 5-slot) HeroUI color system.
const colorOverrideClass: Record<string, string> = {
  navy: 'bg-[var(--color-navy)]! hover:bg-[var(--color-navy-light)]! text-white! shadow-none!',
};

export function Button({
  variant = 'primary',
  size = 'md',
  fullWidth = false,
  isLoading = false,
  leftIcon,
  rightIcon,
  disabled,
  className = '',
  children,
  ...props
}: ButtonProps) {
  const overrideClass = colorOverrideClass[variant] || '';

  return (
    <HeroButton
      {...props}
      variant={variantMap[variant] || 'primary'}
      size={size}
      fullWidth={fullWidth}
      isDisabled={disabled || isLoading}
      className={[overrideClass, className].filter(Boolean).join(' ')}
    >
      {isLoading ? (
        <Loader2 size={16} className="animate-spin" />
      ) : (
        <>
          {leftIcon}
          {children}
          {rightIcon}
        </>
      )}
    </HeroButton>
  );
}

