:root {
  --background: var(--color-canvas);
  --foreground: var(--color-text);

  --surface: var(--color-surface);
  --surface-foreground: var(--color-text);
  --surface-secondary: var(--color-surface-alt);
  --surface-tertiary: var(--color-surface-alt);

  --overlay: var(--color-surface);
  --overlay-foreground: var(--color-text);

  --muted: var(--color-text-tertiary);

  --default: var(--color-surface-alt);
  --default-foreground: var(--color-text);

  --accent: var(--color-orange);
  --accent-foreground: #FFFFFF;

  --success: var(--color-success);
  --success-foreground: #FFFFFF;
  --warning: var(--color-warning);
  --warning-foreground: #2B1D02;
  --danger: var(--color-error);
  --danger-foreground: #FFFFFF;

  --field-background: var(--color-surface);
  --field-foreground: var(--color-text);
  --field-placeholder: var(--color-text-muted);
  --field-border: var(--color-border);

  --border: var(--color-border);
  --separator: var(--color-border);
  --focus: var(--color-orange);
  --link: var(--color-orange);

  --radius: var(--radius-sm);
  --backdrop: var(--modal-backdrop);
}

/* ─── Base Reset ─── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  -webkit-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

html, body { height: 100%; overflow-x: hidden; }

body {
  font-family: var(--font-sans);
  background: var(--color-canvas);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100dvh;
}

/* ─── Accessibility ─── */
:focus-visible {
  outline: 2px solid var(--color-orange);
  outline-offset: 2px;
  border-radius: var(--radius-xs);
}

.skip-link {
  position: absolute;
  top: -9999px;
  left: 16px;
  z-index: 9999;
  padding: 8px 16px;
  background: var(--color-orange);
  color: #FFFFFF;
  font-weight: 700;
  font-size: 13px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: var(--shadow-md);
  transition: top 0.2s ease;
}
.skip-link:focus { top: 16px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ─── Custom Scrollbar ─── */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--color-border-hover); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: var(--color-text-muted); }

/* ═══════════════════════════════════════════════════
   APP SHELL
   ═══════════════════════════════════════════════════ */

.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
  max-width: 100vw;
  overflow-x: hidden;
  background: var(--color-canvas);
}

.app-page-content {
  flex: 1;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 0 var(--spacing-page);
  padding-bottom: 100px;
}
@media (min-width: 768px) { .app-page-content { max-width: 720px; padding: 0 32px 48px; } }
@media (min-width: 1024px) { .app-page-content { max-width: 960px; } }

