  | 'lead'
  | 'onboarding'
  | 'official_kyc_pending'
  | 'filing_in_progress'
  | 'bank_opening'
  | 'active'
  | 'renewal_due'
  | 'suspended'
  | 'archived';
export type TrackType = 'remote' | 'gulf';
export type DocumentCategory =
  | 'trade_license'
  | 'moa_articles'
  | 'share_certificate'
  | 'certificate_of_incumbency'
  | 'tax_trn_certificate'
  | 'nominee_poa'
  | 'preflight_id'
  | 'other';
export type DocumentStatus = 'active' | 'archived' | 'superseded';
export type MilestoneStatus = 'pending' | 'in_progress' | 'completed';
export type OrderType =
  | 'new_formation'
  | 'shelf_transfer'
  | 'annual_renewal'
  | 'tax_filing'
  | 'add_on_bank'
  | 'visa_service';
export type PaymentStatus = 'unpaid' | 'processing' | 'paid' | 'failed' | 'refunded';
export type RenewalStatus = 'upcoming' | 'invoiced' | 'paid' | 'overdue' | 'renewed';
export type NotificationType = 'info' | 'success' | 'warning' | 'action_required';
export type DeliveryStatus =
  | 'not_applicable'
  | 'queued'
  | 'sent'
  | 'delivered'
  | 'read'
  | 'failed';

// ─── Row Interfaces ─────────────────────────────────────────────────────────

export interface User {
  id: string;
  email: string;
  whatsapp_number: string;
  full_name: string;
  country_residence: string | null;
  role: UserRole;
  avatar_url: string | null;
  magic_token: string | null;
